const dados = $input.first().json;
const servicosCodes = {
  'consulta':     { descricao: 'Consulta odontológica',                    codigo_servico: '0401', aliquota_iss: 2.0 },
  'limpeza':      { descricao: 'Limpeza e profilaxia dental',              codigo_servico: '0401', aliquota_iss: 2.0 },
  'restauracao':  { descricao: 'Restauração dentária',                     codigo_servico: '0401', aliquota_iss: 2.0 },
  'extracao':     { descricao: 'Extração dentária',                        codigo_servico: '0401', aliquota_iss: 2.0 },
  'clareamento':  { descricao: 'Clareamento dental',                       codigo_servico: '0401', aliquota_iss: 2.0 },
  'ortodontia':   { descricao: 'Tratamento ortodôntico (mensalidade)',     codigo_servico: '0401', aliquota_iss: 2.0 },
  'implante':     { descricao: 'Implante dentário',                        codigo_servico: '0401', aliquota_iss: 2.0 },
  'canal':        { descricao: 'Tratamento de canal (endodontia)',         codigo_servico: '0401', aliquota_iss: 2.0 },
  'protese':      { descricao: 'Prótese dentária',                         codigo_servico: '0401', aliquota_iss: 2.0 }
};
const tipoServico = (dados.tipo_servico || 'consulta').toLowerCase();
const servico = servicosCodes[tipoServico] || servicosCodes['consulta'];
const valorTotal = parseFloat(dados.valor || 0);
const valorISS = parseFloat((valorTotal * servico.aliquota_iss / 100).toFixed(2));
const numeroRPS = 'RPS-' + Date.now();
return [{
  json: {
    prestador: {
      cnpj:                $vars.CNPJ_CONSULTORIO,
      inscricao_municipal: $vars.INSCRICAO_MUNICIPAL,
      razao_social:        $vars.RAZAO_SOCIAL,
      codigo_municipio:    $vars.CODIGO_MUNICIPIO_IBGE
    },
    tomador: {
      cpf:        dados.cpf_paciente || '',
      nome:       dados.nome_paciente || dados.nomePaciente || '',
      email:      dados.email_paciente || '',
      telefone:   dados.telefone_paciente || '',
      logradouro: dados.endereco_logradouro || '',
      numero:     dados.endereco_numero || 'S/N',
      bairro:     dados.endereco_bairro || '',
      municipio:  dados.endereco_municipio || '',
      uf:         dados.endereco_uf || '',
      cep:        dados.endereco_cep || ''
    },
    servico: {
      descricao:        servico.descricao + (dados.descricao_adicional ? ' — ' + dados.descricao_adicional : ''),
      codigo_servico:   servico.codigo_servico,
      aliquota_iss:     servico.aliquota_iss,
      valor_servicos:   valorTotal.toFixed(2),
      valor_iss:        valorISS.toFixed(2),
      valor_liquido:    valorTotal.toFixed(2)
    },
    pacienteId:      dados.paciente_id || null,
    consultaId:      dados.consulta_id || null,
    telefone_paciente: dados.telefone_paciente || '',
    email_paciente:    dados.email_paciente || '',
    numeroRPS,
    mesCompetencia:  new Date().toISOString().substring(0, 7)
  }
}];

const nfResult = $input.first().json;
const registro = Array.isArray(nfResult) ? nfResult[0] : nfResult;
const dados = $('Prepara Dados da NF').item.json;
return [{ json: { supabaseId: registro.id, ...dados } }];

const nfData = $input.first().json;
const dadosOriginais = $('Extrai ID do Registro NF').item.json;
return [{
  json: {
    supabaseId:      dadosOriginais.supabaseId,
    status:          nfData.status || 'processando',
    numeroNF:        nfData.numero || '',
    ref:             nfData.ref || $('Emite NFS-e (Focus NF-e)').item.json.ref || '',
    chaveAcesso:     nfData.chave_acesso || '',
    linkPDF:         nfData.caminho_danfse || nfData.url_danfse || '',
    linkXML:         nfData.caminho_xml_nota_fiscal || '',
    tomadorNome:     dadosOriginais.tomador.nome,
    tomadorTelefone: dadosOriginais.telefone_paciente,
    tomadorEmail:    dadosOriginais.email_paciente,
    valorServico:    dadosOriginais.servico.valor_servicos,
    descricaoServico: dadosOriginais.servico.descricao,
    dataEmissao:     new Date().toLocaleDateString('pt-BR')
  }
}];

